// ── 初始設定 ──────────────────────────────────────────────────────────────
function setup() {
	createCanvas(windowWidth, windowHeight);
	// 每個對話生成一次隨機種子（重整時觸發）
	currentSeed = floor(random(1000000));
	randomSeed(currentSeed);
	noiseSeed(currentSeed);
	buildTable();
	buildPapers();

	// 自動播放按鈕監聽器
	document.getElementById('play-btn').addEventListener('click', () => {
		autoplay = !autoplay;
		let btn = document.getElementById('play-btn');
		if (autoplay) {
			btn.classList.add('active');
			if (!audioCtx) {
				audioCtx = new(window.AudioContext || window.webkitAudioContext)();
			}
			if (audioCtx.state === 'suspended') {
				audioCtx.resume();
			}
			melodyIndex = 0;
			nextNoteTime = millis() + 300;
		} else {
			btn.classList.remove('active');
		}
	});
}

function draw() {
	image(tableG, 0, 0);

	// 自動播放編曲器時鐘
	if (autoplay && millis() > nextNoteTime) {
		let step = DALI_BREEZE_MELODY[melodyIndex];
		triggerPaperByNote(step.note);

		// 極慢、具呼吸感的羊毛氈鋼琴節奏：1 拍 = 660 毫秒
		let beatLen = 660;
		nextNoteTime = millis() + step.dur * beatLen;
		melodyIndex = (melodyIndex + 1) % DALI_BREEZE_MELODY.length;
	}

	// 溫柔、像棉花般具緩衝感的彈簧物理效果（臨界阻尼）
	for (let p of papers) {
		let force = -0.06 * (p.scale - p.targetScale); // 低剛度 = 更沉穩的按壓感
		p.vel = (p.vel + force) * 0.70; // 高摩擦/阻力 = 零數位抖動
		p.scale += p.vel;

		let sForce = -0.06 * (p.shadowScale - p.targetScale);
		p.shadowScaleVel = (p.shadowScaleVel + sForce) * 0.65;
		p.shadowScale += p.shadowScaleVel;

		// 衰減半透明的光澤掃拂微光
		if (p.glowVal > 0) {
			p.glowVal *= 0.94;
		}
	}

	// 繪製紙張（由後至前堆疊繪製）
	for (let p of papers) drawPaper(p);

	// 更新並繪製有機塵埃粒子
	for (let i = particles.length - 1; i >= 0; i--) {
		let pt = particles[i];
		pt.update();
		pt.draw();
		if (pt.alpha <= 0) {
			particles.splice(i, 1);
		}
	}
}

// ── 貝氏曲線輔助函式 ─────────────────────────────────────────────────────
function bPt(t, p0, p1, p2, p3) {
	let m = 1 - t;
	return {
		x: m * m * m * p0.x + 3 * m * m * t * p1.x + 3 * m * t * t * p2.x + t * t * t * p3.x,
		y: m * m * m * p0.y + 3 * m * m * t * p1.y + 3 * m * t * t * p2.y + t * t * t * p3.y
	};
}

function bTang(t, p0, p1, p2, p3) {
	var m = 1 - t;
	return {
		x: 3 * m * m * (p1.x - p0.x) + 6 * m * t * (p2.x - p1.x) + 3 * t * t * (p3.x - p2.x),
		y: 3 * m * m * (p1.y - p0.y) + 6 * m * t * (p2.y - p1.y) + 3 * t * t * (p3.y - p2.y)
	};
}

// ── 沿著 S 型路徑構建紙張石板 ───────────────────────────────────
function buildPapers() {
	papers = [];
	const N = 35; // 茂密鋪設的紙張小路

	// 基礎起終點為對角線，但控制點在每次重整時都有隨機有機變化
	const P0 = {
		x: 0.04,
		y: 0.96
	};
	const P1 = {
		x: random(0.06, 0.24),
		y: random(0.18, 0.42)
	};
	const P2 = {
		x: random(0.72, 0.90),
		y: random(0.56, 0.82)
	};
	const P3 = {
		x: 0.96,
		y: 0.04
	};

	for (let i = 0; i < N; i++) {
		let t = i / (N - 1);
		let depth = t;

		// 曲線上的座標位置
		let pos = bPt(t, P0, P1, P2, P3);
		let cx = pos.x * width;
		let cy = pos.y * height;

		// 螢幕空間中的切線角度
		let tang = bTang(t, P0, P1, P2, P3);
		let pathAngle = atan2(tang.y * height, tang.x * width);

		// 帶有輕微隨機雜訊的垂直路徑旋轉
		let rot = pathAngle - HALF_PI + random(-0.08, 0.08);

		// 透視比例與不透明度
		let scale = map(depth, 0, 1, 1.0, 0.32);
		let op = map(depth, 0, 1, 1.00, 0.28);

		// 適合石板般鋪設的寬比例形狀
		let w = floor(310 * scale);
		let h = floor(200 * scale);

		let type = PAPERS[TYPE_SEQ[i % TYPE_SEQ.length]];
		let g = buildTexture(type, w, h);
		let edge = buildEdge(w, h, rot);

		papers.push({
			index: i,
			g,
			edge,
			cx,
			cy,
			w,
			h,
			rot,
			type,
			op,
			scale: 1.0,
			targetScale: 1.0,
			vel: 0,
			shadowScale: 1.0,
			shadowScaleVel: 0,
			glowVal: 0.0,
			clickX: 0.0,
			clickY: 0.0
		});
	}
}

// ── 桌面紋理 ──────────────────────────────────────────────────────
function buildTable() {
	tableG = createGraphics(width, height);
	tableG.background(19, 14, 9);
	tableG.noStroke();
	for (let y = 0; y < height; y++) {
		let n = noise(y * 0.006);
		let n2 = noise(y * 0.022 + 50) * 0.38;
		let v = map(n + n2, 0, 1.38, 13, 33);
		tableG.fill(v + 7, v + 1, v - 3);
		tableG.rect(0, y, width, 1);
	}
	for (let i = 0; i < 90; i++) {
		let sy = random(-50, height + 50);
		let c = floor(random(30, 58));
		tableG.stroke(c, floor(c * 0.63), floor(c * 0.36), random(12, 42));
		tableG.strokeWeight(random(0.3, 1.8));
		tableG.noFill();
		tableG.beginShape();
		for (let x = -10; x <= width + 10; x += 6)
			tableG.curveVertex(x, sy + (noise(x * 0.007, i * 3.8) - 0.5) * 85);
		tableG.endShape();
	}
	// 暗角效果
	let vg = tableG.drawingContext.createRadialGradient(
		width / 2, height / 2, height * 0.1,
		width / 2, height / 2, height * 0.92);
	vg.addColorStop(0, 'rgba(0,0,0,0)');
	vg.addColorStop(1, 'rgba(0,0,0,0.65)');
	tableG.drawingContext.fillStyle = vg;
	tableG.drawingContext.fillRect(0, 0, width, height);
}

// ── 紙張紋理（多層次、高擬真） ───────────────────────
function buildTexture(p, w, h) {
	var g = createGraphics(w, h);

	// 第一層：多倍頻柏林雜訊基底（粗糙 + 細緻）
	g.noStroke();
	for (let x = 0; x < w; x += 2) {
		for (let y = 0; y < h; y += 2) {
			let n1 = noise(x * 0.008 + p.bg[0] * 0.01, y * 0.008 + p.bg[1] * 0.01) * p.bgV;
			var n2 = noise(x * 0.032 + 80, y * 0.028 + 80) * p.bgV * 0.42;
			let n3 = noise(x * 0.12 + 40, y * 0.11 + 40) * p.bgV * 0.18;
			var v = n1 - n2 + n3;
			g.fill(constrain(p.bg[0] + v, 0, 255),
				constrain(p.bg[1] + v, 0, 255),
				constrain(p.bg[2] + v, 0, 255));
			g.rect(x, y, 2, 2);
		}
	}

	// 第二層：細微的造紙網格壓印（手工紙獨有的隱約網格）
	g.noFill();
	let gridSpacing = 8;
	g.strokeWeight(0.3);
	g.stroke(p.bg[0] - 18, p.bg[1] - 18, p.bg[2] - 15, 22);
	for (let x = 0; x < w; x += gridSpacing) g.line(x, 0, x, h);
	for (let y = 0; y < h; y += gridSpacing) g.line(0, y, w, y);

	// 第三層：修長的單根紙張纖維絲（主要可見纖維）
	g.noFill();
	for (let i = 0; i < 420; i++) {
		let fc = random(p.fibers);
		let x = random(-10, w + 10),
			y = random(-10, h + 10);
		let len = random(8, 95),
			ang = random(TWO_PI);
		g.stroke(fc[0], fc[1], fc[2], random(fc[3] * 0.5, fc[3] * 1.2));
		g.strokeWeight(random(0.12, 0.85));
		let ex = x + cos(ang) * len,
			ey = y + sin(ang) * len;
		let mx = (x + ex) / 2 + random(-len * 0.3, len * 0.3);
		let my = (y + ey) / 2 + random(-len * 0.3, len * 0.3);
		g.bezier(x, y, mx, my, mx, my, ex, ey);
	}

	// 第四層：短促的交叉纖維（紙漿質感）
	for (let i = 0; i < 200; i++) {
		var fc = random(p.fibers);
		var x = random(w),
			y = random(h);
		var len = random(3, 22),
			ang = random(TWO_PI);
		g.stroke(fc[0], fc[1], fc[2], random(30, 65));
		g.strokeWeight(random(0.1, 0.45));
		g.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
	}

	// 第五層：纖維束（2-3 根緊密相鄰的平行纖維絲）
	for (let i = 0; i < 35; i++) {
		var fc = random(p.fibers);
		var x = random(w),
			y = random(h);
		var len = random(30, 90),
			ang = random(TWO_PI);
		let perp = ang + HALF_PI;
		let count = floor(random(2, 4));
		for (let b = 0; b < count; b++) {
			let off = (b - count / 2) * random(1.5, 4);
			let bx = x + cos(perp) * off,
				by = y + sin(perp) * off;
			var ex = bx + cos(ang) * len,
				ey = by + sin(ang) * len;
			var mx = (bx + ex) / 2 + random(-12, 12),
				my = (by + ey) / 2 + random(-12, 12);
			g.stroke(fc[0], fc[1], fc[2], random(35, 70));
			g.strokeWeight(random(0.15, 0.6));
			g.bezier(bx, by, mx, my, mx, my, ex, ey);
		}
	}

	// 第六層：夾雜物
	if (p.inc === 'botanical') {
		g.noStroke();
		for (let i = 0; i < 140; i++) {
			var c = p.incC;
			var bx = random(w),
				by = random(h);
			let bw = random(4, 22),
				bh = random(2, 9);
			g.push();
			g.translate(bx, by);
			g.rotate(random(TWO_PI));
			g.fill(c[0] + random(-18, 18), c[1] + random(-18, 18), c[2] + random(-18, 18), random(50, 160));
			g.ellipse(0, 0, bw, bh);
			g.stroke(c[0] - 15, c[1] - 15, c[2] - 12, random(60, 110));
			g.strokeWeight(0.35);
			g.noFill();
			g.line(-bw / 2, 0, bw / 2, 0);
			g.pop();
		}
		g.noFill();
		for (let i = 0; i < 12; i++) {
			var c = p.incC;
			g.stroke(c[0] - 10, c[1] - 10, c[2] - 8, random(70, 140));
			g.strokeWeight(random(0.6, 1.4));
			let sx = random(w),
				sy = random(h);
			g.line(sx, sy, sx + random(-30, 30), sy + random(-30, 30));
		}
	} else if (p.inc === 'floral') {
		g.noStroke();
		for (let i = 0; i < 6; i++) {
			var c = p.incC;
			let fx = random(w * 0.08, w * 0.92),
				fy = random(h * 0.08, h * 0.92);
			let sz = random(18, 60);
			for (let petal = 0; petal < 5; petal++) {
				let pa = (petal / 5) * TWO_PI;
				let px = fx + cos(pa) * sz * 0.35,
					py = fy + sin(pa) * sz * 0.35;
				for (let r = sz * 0.6; r > 0; r -= 2.5) {
					g.fill(c[0] + random(-8, 8), c[1] + random(-8, 8), c[2] + random(-8, 8),
						map(r, 0, sz * 0.6, 18, 4));
					g.ellipse(px + random(-2, 2), py + random(-2, 2), r * 1.3, r);
				}
			}
			g.fill(c[0] - 20, c[1] - 20, c[2] - 18, 55);
			g.ellipse(fx, fy, sz * 0.18, sz * 0.18);
		}
	}

	// 第七層：深色紙雜質雜點
	g.noStroke();
	for (let i = 0; i < 100; i++) {
		g.fill(p.bg[0] - 40 + random(-10, 10), p.bg[1] - 38 + random(-10, 10),
			p.bg[2] - 32 + random(-10, 10), random(20, 80));
		let sp = random(0.4, 2.8);
		g.ellipse(random(w), random(h), sp, sp * random(0.5, 2));
	}

	// 第八層：暈染效果
	g.noFill();
	for (let i = 0; i < 8; i++) {
		var bx = random(w),
			by = random(h);
		let br = random(12, 45);
		let bg = g.drawingContext.createRadialGradient(bx, by, 0, bx, by, br);
		bg.addColorStop(0, `rgba(${p.bg[0]-25},${p.bg[1]-25},${p.bg[2]-20},0.12)`);
		bg.addColorStop(1, 'rgba(0,0,0,0)');
		g.drawingContext.fillStyle = bg;
		g.drawingContext.fillRect(bx - br, by - br, br * 2, br * 2);
	}

	// 第九層：紙張摺痕
	g.noFill();
	for (let i = 0; i < 4; i++) {
		let x1 = random(w * 0.1, w * 0.9),
			y1 = random(h * 0.1, h * 0.9);
		let x2 = x1 + random(-70, 70),
			y2 = y1 + random(-70, 70);
		g.stroke(p.bg[0] - 28, p.bg[1] - 26, p.bg[2] - 22, random(18, 38));
		g.strokeWeight(random(0.3, 0.9));
		g.line(x1, y1, x2, y2);
		g.stroke(255, 255, 255, random(8, 20));
		g.strokeWeight(random(0.25, 0.65));
		g.line(x1 + 0.8, y1 + 0.8, x2 + 0.8, y2 + 0.8);
	}

	return g;
}

// ── 毛邊效果（手工紙撕裂毛邊） ───────────────────────────────────────────────────────
function buildEdge(w, h, rot) {
	let verts = [];
	let segs = 44;
	let rough = 4.5;

	function pv(lx, ly) {
		// 旋轉後的局部相對座標
		verts.push({
			x: lx * cos(rot) - ly * sin(rot),
			y: lx * sin(rot) + ly * cos(rot)
		});
	}

	for (let i = 0; i <= segs; i++) pv(-w / 2 + (i / segs) * w, -h / 2 + random(-rough, rough));
	for (let i = 0; i <= segs; i++) pv(w / 2 + random(-rough, rough), -h / 2 + (i / segs) * h);
	for (let i = 0; i <= segs; i++) pv(w / 2 - (i / segs) * w, h / 2 + random(-rough, rough));
	for (let i = 0; i <= segs; i++) pv(-w / 2 + random(-rough, rough), h / 2 - (i / segs) * h);

	return verts;
}

// ── 繪製單張紙張石板 ───────────────────────────────────────────────
function drawPaper(paper) {
	let ctx = drawingContext;
	var edge = paper.edge;
	var op = paper.op;
	let s = paper.scale;
	let shS = paper.shadowScale;

	// 陰影效果
	ctx.save();
	ctx.translate(paper.cx, paper.cy);
	ctx.scale(shS, shS);
	ctx.shadowColor = `rgba(6,4,2,${0.55*op})`;
	ctx.shadowBlur = 22 * op * shS;
	ctx.shadowOffsetX = 5 * op * shS;
	ctx.shadowOffsetY = 9 * op * shS;
	ctx.globalAlpha = op;
	ctx.fillStyle = `rgb(${paper.type.bg[0]},${paper.type.bg[1]},${paper.type.bg[2]})`;
	ctx.beginPath();
	ctx.moveTo(edge[0].x, edge[0].y);
	for (let i = 1; i < edge.length; i++) ctx.lineTo(edge[i].x, edge[i].y);
	ctx.closePath();
	ctx.fill();
	ctx.restore();

	// 紋理表面
	ctx.save();
	ctx.translate(paper.cx, paper.cy);
	ctx.scale(s, s);
	ctx.globalAlpha = op;

	ctx.beginPath();
	ctx.moveTo(edge[0].x, edge[0].y);
	for (let i = 1; i < edge.length; i++) ctx.lineTo(edge[i].x, edge[i].y);
	ctx.closePath();
	ctx.clip();

	ctx.save();
	ctx.rotate(paper.rot);
	ctx.drawImage(paper.g.elt, -paper.w / 2, -paper.h / 2, paper.w, paper.h);
	ctx.restore();

	// 觸碰時的紙張纖維漫反射光暈（模擬光線在手工紙內部散射的效果）
	if (paper.glowVal > 0.005) {
		ctx.save();
		let radGrd = ctx.createRadialGradient(
			paper.clickX, paper.clickY, 0,
			paper.clickX, paper.clickY, paper.w * 0.75
		);
		let glowCol = `rgba(255, 238, 202, ${0.46 * paper.glowVal * op})`;
		radGrd.addColorStop(0, glowCol);
		radGrd.addColorStop(0.35, `rgba(238, 200, 155, ${0.22 * paper.glowVal * op})`);
		radGrd.addColorStop(1, 'rgba(0,0,0,0)');
		ctx.fillStyle = radGrd;
		ctx.globalCompositeOperation = 'screen';
		ctx.beginPath();
		ctx.moveTo(edge[0].x, edge[0].y);
		for (let i = 1; i < edge.length; i++) ctx.lineTo(edge[i].x, edge[i].y);
		ctx.closePath();
		ctx.fill();
		ctx.restore();
	}

	// 邊緣高光筆觸
	ctx.strokeStyle = `rgba(255,252,245,${0.16*op})`;
	ctx.lineWidth = 1.2;
	ctx.beginPath();
	ctx.moveTo(edge[0].x, edge[0].y);
	for (let i = 1; i < edge.length; i++) ctx.lineTo(edge[i].x, edge[i].y);
	ctx.closePath();
	ctx.stroke();
	ctx.restore();
}

// ── 點在多邊形內部的相交檢測器 ──────────────────────────────
function isPointInPoly(pt, poly) {
	var x = pt.x,
		y = pt.y;
	let inside = false;
	for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
		let xi = poly[i].x,
			yi = poly[i].y;
		let xj = poly[j].x,
			yj = poly[j].y;
		let intersect = ((yi > y) !== (yj > y)) &&
			(x < (xj - xi) * (y - yi) / (yj - yi) + xi);
		if (intersect) inside = !inside;
	}
	return inside;
}

// ── 慵懶溫暖的紙漿棉絮與陽光微塵粒子 ────────────────────
class PulpDustMote {
	constructor(x, y, baseColor) {
		this.x = x;
		this.y = y;
		// 極其緩慢的懸浮飄動
		this.vx = random(-1.2, 1.2);
		this.vy = random(-1.6, -0.5);

		// 舒適溫馨的搖擺頻率
		this.noisePhaseX = random(100);
		this.noisePhaseY = random(100);
		this.swaySpeed = random(0.015, 0.035);

		let choice = random(1);
		if (choice < 0.42) {
			// 溫暖的棉絮
			this.r = 252;
			this.g = 246;
			this.b = 235;
		} else if (choice < 0.72) {
			// 金黃色的陽光微塵
			this.r = 246 + random(-5, 9);
			this.g = 212 + random(-10, 10);
			this.b = 152 + random(-12, 12);
		} else {
			// 柔和的植物有機染色
			this.r = baseColor[0] + random(10, 25);
			this.g = baseColor[1] + random(10, 20);
			this.b = baseColor[2] + random(15, 30);
		}

		this.size = random(8, 20);
		this.alpha = random(130, 200);
		this.decay = random(1.6, 2.8); // 能夠優雅地飄移很長一段時間
	}

	update() {
		// 在溫暖的對流微風中搖擺
		this.vx += (noise(frameCount * this.swaySpeed + this.noisePhaseX) - 0.5) * 0.12;
		this.vy += (noise(frameCount * this.swaySpeed + this.noisePhaseY) - 0.5) * 0.08;

		this.x += this.vx;
		this.y += this.vy;
		this.vx *= 0.98;
		this.vy *= 0.98;
		this.alpha -= this.decay;
	}

	draw() {
		if (this.alpha <= 0) return;
		push();
		translate(this.x, this.y);
		noStroke();

		// 多層徑向模糊疊加，以模擬極其柔軟的棉絮質感
		for (let r = 1; r >= 0.25; r -= 0.25) {
			fill(this.r, this.g, this.b, this.alpha * (1 - r) * 0.36);
			ellipse(0, 0, this.size * r * 1.5, this.size * r * 1.25);
		}
		pop();
	}
}

// ── 互動滑鼠點擊與羊毛氈鋼琴物理建模合成 ────────────────
let audioCtx = null;

function playPiano(midiNote) {
	// 在使用者首次點擊時初始化 Web Audio 上下文（遵循瀏覽器自動播放安全策略）
	if (!audioCtx) {
		audioCtx = new(window.AudioContext || window.webkitAudioContext)();
	}
	if (audioCtx.state === 'suspended') {
		audioCtx.resume();
	}

	// 將 MIDI 音符數值轉換為十二平均律頻率
	let freq = 440.0 * Math.pow(2.0, (midiNote - 69.0) / 12.0);
	let now = audioCtx.currentTime;

	// ── 增益節點用於羊毛氈鋼琴的絲滑衰減包絡 ──
	let gainNode = audioCtx.createGain();
	gainNode.gain.setValueAtTime(0, now);
	// 緩衝的慢起音（45 毫秒起音，而非 4 毫秒的硬擊弦），模擬加厚羊毛氈的消音效果
	gainNode.gain.linearRampToValueAtTime(0.18, now + 0.045);
	// 悠長、華麗且自然的鋼琴餘音衰減
	gainNode.gain.exponentialRampToValueAtTime(0.001, now + 3.8);

	// ── 低通濾波器用於深沉的羊毛氈鋼琴溫潤音色（濾除數位高頻雜音） ──
	let filter = audioCtx.createBiquadFilter();
	filter.type = 'lowpass';
	filter.Q.setValueAtTime(0.6, now); // 低 Q 值帶來極其溫潤的木質共鳴
	filter.frequency.setValueAtTime(680, now);
	filter.frequency.exponentialRampToValueAtTime(160, now + 2.0);

	// ── 多諧波音色震盪器 ──
	// 基音（純正弦波）
	let oscFundamental = audioCtx.createOscillator();
	oscFundamental.type = 'sine';
	oscFundamental.frequency.setValueAtTime(freq, now);

	// 一次泛音：高一個八度（三角波，模擬中空木質共鳴板諧振）
	let oscOctave = audioCtx.createOscillator();
	oscOctave.type = 'triangle';
	oscOctave.frequency.setValueAtTime(freq * 2.0, now);
	let gainOctave = audioCtx.createGain();
	gainOctave.gain.setValueAtTime(0.05, now);
	gainOctave.gain.exponentialRampToValueAtTime(0.001, now + 0.85);

	// 二次泛音：高一個八度加五度（正弦波，極小音量點綴）
	let oscFifth = audioCtx.createOscillator();
	oscFifth.type = 'sine';
	oscFifth.frequency.setValueAtTime(freq * 3.0, now);
	let gainFifth = audioCtx.createGain();
	gainFifth.gain.setValueAtTime(0.015, now);
	gainFifth.gain.exponentialRampToValueAtTime(0.001, now + 0.42);

	// ── 柔化的琴槌敲擊聲 ──
	let hammer = audioCtx.createOscillator();
	hammer.type = 'sine';
	hammer.frequency.setValueAtTime(freq * 4.0, now);
	hammer.frequency.exponentialRampToValueAtTime(freq, now + 0.025);
	let hammerGain = audioCtx.createGain();
	hammerGain.gain.setValueAtTime(0.02, now); // 溫和的木質敲擊感，而非尖銳的金屬叮噹聲
	hammerGain.gain.exponentialRampToValueAtTime(0.001, now + 0.035);

	// 連接各個諧波音色
	oscFundamental.connect(gainNode);

	oscOctave.connect(gainOctave);
	gainOctave.connect(gainNode);

	oscFifth.connect(gainFifth);
	gainFifth.connect(gainNode);

	hammer.connect(hammerGain);
	hammerGain.connect(gainNode);

	gainNode.connect(filter);
	filter.connect(audioCtx.destination);

	// 啟動震盪器
	oscFundamental.start(now);
	oscOctave.start(now);
	oscFifth.start(now);
	hammer.start(now);

	oscFundamental.stop(now + 4.0);
	oscOctave.stop(now + 4.0);
	oscFifth.stop(now + 4.0);
	hammer.stop(now + 4.0);
}

// C 大調自然音階生成器：將 35 張紙張（0 到 34）一一映射到完全獨一無二的暖白鍵音高！
// 從最前下方深沉的 C3（48）開始，一路上升到最後上方清脆如音樂盒般的 B7（107）。
function getDiatonicNote(index) {
	let baseNote = 48; // C3（溫暖的低音區）
	let diatonicOffsets = [0, 2, 4, 5, 7, 9, 11]; // Do, Re, Mi, Fa, Sol, La, Si
	let octave = floor(index / 7);
	var step = index % 7;
	return baseNote + octave * 12 + diatonicOffsets[step];
}

let lastDraggedPaperIndex = -1;

function mousePressed() {
	for (let i = papers.length - 1; i >= 0; i--) {
		let p = papers[i];
		let lx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - p.cx;
		let ly = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - p.cy;

		if (isPointInPoly({
				x: lx,
				y: ly
			}, p.edge)) {
			lastDraggedPaperIndex = p.index; // 鎖定起始拖曳紙張

			// 具緩衝感的下陷壓感
			p.scale = 0.92;
			p.shadowScale = 0.92;

			// 觸發光掃微光
			p.glowVal = 1.0;
			p.clickX = lx;
			p.clickY = ly;

			// 噴發溫柔漂浮的棉絮微塵
			let pColor = p.type.fibers[0] || [210, 195, 175];
			var count = floor(random(9, 14));
			for (let j = 0; j < count; j++) {
				particles.push(new PulpDustMote((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), pColor));
			}

			// ── 鋼琴音高映射 ──
			// 現在每一張紙張石板都擁有 100% 專屬、獨一無二的音高！
			let midiNote = getDiatonicNote(p.index);
			playPiano(midiNote);

			break;
		}
	}
}

function mouseReleased() {
	lastDraggedPaperIndex = -1;
}

function mouseDragged() {
	for (let i = papers.length - 1; i >= 0; i--) {
		var p = papers[i];
		var lx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - p.cx;
		var ly = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - p.cy;

		if (isPointInPoly({
				x: lx,
				y: ly
			}, p.edge)) {
			if (p.index !== lastDraggedPaperIndex) {
				lastDraggedPaperIndex = p.index;

				// 具緩衝感的下陷壓感
				p.scale = 0.92;
				p.shadowScale = 0.92;

				// 觸發光掃微光
				p.glowVal = 1.0;
				p.clickX = lx;
				p.clickY = ly;

				// 噴發溫柔漂浮的微塵（數量稍減以優化拖曳效能）
				var pColor = p.type.fibers[0] || [210, 195, 175];
				var count = floor(random(4, 7));
				for (let j = 0; j < count; j++) {
					particles.push(new PulpDustMote((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), pColor));
				}

				// 播放音符
				var midiNote = getDiatonicNote(p.index);
				playPiano(midiNote);
			}
			return; // 停止繼續檢測下方重疊的紙張
		}
	}
	// 滑鼠拖曳至紙張路徑之外，重設鎖定狀態
	lastDraggedPaperIndex = -1;
}

// ── 自動播放編曲器音符至紙張對應的觸發映射 ────────────────────────────
function triggerPaperByNote(noteVal) {
	// 尋找唯一音高與旋律音符最接近的那張紙張！
	let bestIdx = 0;
	let minDiff = 999;
	for (let i = 0; i < papers.length; i++) {
		let paperNote = getDiatonicNote(i);
		let diff = abs(paperNote - noteVal);
		if (diff < minDiff) {
			minDiff = diff;
			bestIdx = i;
		}
	}

	// 在最適配的紙張石板上觸發緩衝下陷動畫
	var p = papers[bestIdx];
	p.scale = 0.92;
	p.shadowScale = 0.92;
	p.glowVal = 1.0;
	p.clickX = random(-p.w / 5, p.w / 5);
	p.clickY = random(-p.h / 5, p.h / 5);

	// 在全域座標上噴發溫柔漂浮的紙漿塵埃粒子
	var pColor = p.type.fibers[0] || [210, 195, 175];
	let worldX = p.cx + p.clickX;
	let worldY = p.cy + p.clickY;
	var count = floor(random(8, 12));
	for (let j = 0; j < count; j++) {
		particles.push(new PulpDustMote(worldX, worldY, pColor));
	}

	// 播放精確校準的鋼琴音符
	playPiano(noteVal);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
	tableG = null;
	papers = [];
	particles = [];
	// 重設視窗大小時重複使用同一個對話種子，以避免小路佈局閃爍跳動
	randomSeed(currentSeed);
	noiseSeed(currentSeed);
	buildTable();
	buildPapers();
}

